//! Wolfram golden replay: peak-pressure/SPL conventions.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/spl_golden.wls` under Wolfram Engine 15.0.0) pins the two
//! conventions every RoomEQ-facing consumer depends on: frequency-domain
//! solvers carry peak amplitudes while SPL references RMS pressure (the
//! `1/Sqrt[2]` factor), and the acoustic reference is exactly 20 uPa. A
//! peak/RMS mix-up is a 3.01 dB systematic shift, so the replay band is far
//! tighter than that confusion distance.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_sim_room::fast_room::{
    rigid_shoebox_mode_frequency_reference, rigid_shoebox_zero_mode_pressure_reference,
};
use sonium_sim_room::room_metrics::{MIN_SPL_DB, peak_pressure_to_spl, spl_to_peak_pressure};
use std::collections::HashMap;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram SPL fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

#[test]
fn peak_pressure_spl_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["peak_spl_db"].exact.contains("0.05/Sqrt[2]"),
        "golden must document the peak-to-RMS design"
    );
    // |0.03 + 0.04i| = 0.05 Pa peak, exactly representable in binary.
    let actual = peak_pressure_to_spl(Complex64::new(0.03, 0.04));
    let expected: f64 = fixture.values["peak_spl_db"].value.parse().unwrap();
    assert!(
        (actual - expected).abs() < 1e-9,
        "Rust {actual} vs Wolfram {expected}"
    );
}

#[test]
fn spl_roundtrip_recovers_peak_pressure() {
    let fixture = parse_fixture();
    let spl: f64 = fixture.values["peak_spl_db"].value.parse().unwrap();
    let recovered = spl_to_peak_pressure(spl, 0.7).expect("finite SPL converts");
    let expected: f64 = fixture.values["roundtrip_peak_pa"].value.parse().unwrap();
    assert!(
        (recovered.norm() - expected).abs() < 1e-15,
        "round-trip magnitude {} vs Wolfram {expected}",
        recovered.norm()
    );
    assert!(
        (recovered.arg() - 0.7).abs() < 1e-15,
        "round-trip phase is preserved"
    );
}

#[test]
fn rigid_shoebox_spectrum_matches_wolfram() {
    let fixture = parse_fixture();
    let dimensions = [5.0, 4.0, 3.0];
    for (indices, name) in [
        ([1, 0, 0], "cav_f_100"),
        ([0, 1, 0], "cav_f_010"),
        ([0, 0, 1], "cav_f_001"),
        ([1, 1, 1], "cav_f_111"),
        ([2, 3, 1], "cav_f_231"),
    ] {
        let actual = rigid_shoebox_mode_frequency_reference(dimensions, indices, 343.0)
            .expect("shoebox inputs are valid");
        let expected: f64 = fixture.values[name].value.parse().unwrap();
        let rel = ((actual - expected) / expected).abs();
        assert!(rel < 1e-12, "{name}: Rust {actual} vs Wolfram {expected}");
    }
}

#[test]
fn rigid_shoebox_zero_mode_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["cav_zero_re"].exact.contains("V = 60"),
        "zero-mode golden must document the room volume"
    );
    let actual = rigid_shoebox_zero_mode_pressure_reference([5.0, 4.0, 3.0], 55.0, 343.0)
        .expect("shoebox inputs are valid");
    let expected_re: f64 = fixture.values["cav_zero_re"].value.parse().unwrap();
    assert!(
        (actual.re - expected_re).abs() < 1e-15,
        "Re(p0): Rust {} vs Wolfram {expected_re}",
        actual.re
    );
    assert!(
        actual.im.abs() < 1e-18,
        "zero mode is purely real, got {}",
        actual.im
    );
}

#[test]
fn sub_floor_pressure_clamps_to_finite_minimum() {
    // 1e-21 Pa sits below the finite floor: the metric contract holds the
    // output at MIN_SPL_DB instead of diverging toward -infinity.
    assert_eq!(
        peak_pressure_to_spl(Complex64::new(1.0e-21, 0.0)),
        MIN_SPL_DB
    );
}
